ruleToc.nextTocUrl:
@js:(function(){var h=''+result,u=''+baseUrl,out='';
var mm=h.match(/<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>(?:(?!<\/a>)[\s\S]){0,80}?下一页/);
if(mm&&mm[1]){out=mm[1];}
else{var cur=1,max=0,has=false,pm=u.match(/[?&]page=(\d+)/);
if(pm){cur=parseInt(pm[1],10)||1;has=true;}
var nr=/[?&]page=(\d+)/g,v;
while((v=nr.exec(h))){var n=parseInt(v[1],10);if(n>max){max=n;}}
var nx=cur+1;
if(max>=nx){out=has?u.replace(/([?&]page=)\d+/,'$1'+nx):(u+(u.indexOf('?')>-1?'&':'?')+'page='+nx);}}
return out;})()
